const menuToggle=document.querySelector(".menu-toggle"),menuLinks=document.querySelector(".menu-links"),app=document.querySelector("#app"),pularLink=document.querySelector(".pular-link");pularLink&&pularLink.addEventListener("click",e=>{e.preventDefault();app.focus()});menuToggle&&menuLinks&&menuToggle.addEventListener("click",()=>{menuLinks.classList.toggle("aberto");menuLinks.classList.contains("aberto")?menuToggle.setAttribute("aria-label","Fechar menu"):menuToggle.setAttribute("aria-label","Abrir menu");menuToggle.setAttribute("aria-expanded",menuLinks.classList.contains("aberto"))});const templates={inicio:"\n        <section>\n            <h2>Sobre a ONG</h2>\n\n            <p>\n                Nossa missão é <em>resgatar animais abandonados e vítimas\n                de maus-tratos</em>, oferecendo cuidados até encontrarem\n                um lar amoroso e responsável.\n            </p>\n        </section>\n\n        <section>\n            <h2>Como ser um colaborador da Patinhas</h2>\n\n            <p>Para ser um doador, você pode:</p>\n\n            <ul>\n                <li>\n                    Ser padrinho/madrinha de um dos nossos animais,\n                    colaborando mensalmente com uma quantia.\n                </li>\n\n                <li>\n                    Fazer doações de ração, medicamentos ou materiais\n                    de higiene diretamente para a ONG.\n                </li>\n\n                <li>\n                    Fazer doações de qualquer valor através do nosso\n                    Pix: <strong>ajudepatinhas@org.com</strong>\n                </li>\n            </ul>\n        </section>\n    ",cadastro:'\n        <form id="formCadastro" novalidate>\n\n            <fieldset>\n\n                <legend>Dados pessoais</legend>\n\n                <label for="nome">Nome completo:</label>\n\n                <input\n                    type="text"\n                    name="nome"\n                    id="nome"\n                    required\n                    autocomplete="name"\n                    aria-describedby="erroNome"\n                    placeholder=" "\n                >\n                <p id="erroNome" class="erro-campo" aria-live="polite"></p>\n\n                <label for="cpf">CPF:</label>\n\n                <input\n                    type="text"\n                    name="cpf"\n                    id="cpf"\n                    required\n                    pattern="\\d{3}\\.\\d{3}\\.\\d{3}-\\d{2}"\n                    aria-describedby="erroCpf"\n                    placeholder=" "\n                >\n\n                <p id="erroCpf" class="erro-campo" aria-live="polite"></p> \n\n\n                <label for="telefone">Telefone:</label>\n\n                <input\n                    type="tel"\n                    name="telefone"\n                    id="telefone"\n                    required\n                    pattern="\\(\\d{2}\\)\\d{5}-\\d{4}"\n                    autocomplete="tel"\n                    aria-describedby="erroTelefone"\n                    placeholder=" "\n                >\n\n                <p id="erroTelefone" class="erro-campo" aria-live="polite"></p>\n\n\n                <label for="cep">CEP:</label>\n\n                <input\n                    type="text"\n                    name="cep"\n                    id="cep"\n                    required\n                    pattern="\\d{5}-\\d{3}"\n                    autocomplete="postal-code"\n                    aria-describedby="erroCep" \n                    placeholder=" "\n                >\n\n                <p id="erroCep" class="erro-campo" aria-live="polite"></p>\n\n\n                <label for="email">E-mail:</label>\n\n                <input\n                    type="email"\n                    name="email"\n                    id="email"\n                    required\n                    autocomplete="email"\n                    aria-describedby="erroEmail"\n                    placeholder=" "\n                >\n\n                <p id="erroEmail" class="erro-campo" aria-live="polite"></p>\n\n            </fieldset>\n\n            <input type="submit" value="Enviar">\n\n            <p id="mensagem" role="status"></p>\n\n        </form>\n    ',projetos:'\n    <section>\n        <h2>Projetos da ONG</h2>\n\n        <div class="projetos-grid">\n\n            <article>\n                <img src="imagens/cachorros-edit.png" alt="Cães resgatados pela ONG" loading="lazy">\n\n                <h2>Resgate Animal</h2>\n\n                <p>\n                    Resgatamos animais abandonados ou vítimas de\n                    maus-tratos, oferecendo atendimento e cuidados\n                    necessários.\n                </p>\n            </article>\n\n\n            <article>\n                <img src="imagens/gatos-edit.png" alt="Gatos resgatados pela ONG" loading="lazy">\n\n                <h2>Lar Temporário</h2>\n\n                <p>\n                    Oferecemos acolhimento temporário aos animais\n                    enquanto buscamos famílias responsáveis para adoção.\n                </p>\n            </article>\n\n\n            <article>\n                <img src="imagens/adocao.jpeg" alt="Mulher adotando cão na campanha de adoção" loading="lazy">\n                <h2>Campanha de Adoção</h2>\n\n                <p>\n                    Promovemos campanhas para encontrar lares\n                    amorosos e responsáveis para nossos animais.\n                </p>\n            </article>\n\n        </div>\n    </section>\n'},titulos={inicio:"Início | ONG Patinhas",cadastro:"Cadastro | ONG Patinhas",projetos:"Projetos | ONG Patinhas"};function carregarPagina(){let e=window.location.hash.replace("#","");""===e&&(e="inicio");templates[e]||(e="inicio");app.innerHTML=templates[e];document.title=titulos[e];"cadastro"===e&&inicializarFormulario();if(menuLinks){menuLinks.classList.remove("aberto");menuToggle.setAttribute("aria-label","Abrir menu")}menuToggle.setAttribute("aria-expanded","false")}window.addEventListener("hashchange",()=>{carregarPagina();app.focus()});carregarPagina();

